import * as React from "react";
import { cn } from "@/lib/utils";

export interface SkeletCardProps extends React.HTMLAttributes<HTMLElement> {
  title: string;
  summary?: string;
  evidenceUri?: string;
  rightsNote?: string;
}

export function SkeletCard({
  title,
  summary,
  evidenceUri,
  rightsNote,
  className,
  children,
  ...props
}: SkeletCardProps): React.JSX.Element {
  return (
    <article
      data-evidence-uri={evidenceUri}
      className={cn("rounded-lg border border-border bg-card p-4", className)}
      {...props}
    >
      <h3 className="text-sm font-semibold">{title}</h3>
      {summary ? <p className="mt-1 text-sm text-muted-foreground">{summary}</p> : null}
      {rightsNote ? <p className="mt-2 text-xs text-muted-foreground">{rightsNote}</p> : null}
      {children}
    </article>
  );
}
